/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "sender">sender</param>
/// <param name = "e">e</param>
[DataEventHandler(tableStr(CustInvoiceTrans), DataEventType::Inserted)]
public static void CustInvoiceTrans_onInserted(Common sender, DataEventArgs e)
{
    boolean                     BPCheck;
    CustInvoiceTrans            custInvoiceTrans        = sender;
    SalesLine                   salesLine               = salesLine::findInventTransId(custInvoiceTrans.InventTransId);
    AVASpecialDiscSalesLine     specialDiscSalesLine    = AVASpecialDiscSalesLine::find(salesLine.InventTransId);
    AVASpecialDiscInvoiceTrans  specialDiscInvoiceTrans;
    AmountCur                   lineAmount;
    CustInvoiceJour             custInvoiceJour = custInvoiceTrans.custInvoiceJour();

    if(e)
    {
        BPCheck = true;
    }

    if (salesLine.PriceUnit && custInvoiceJour.SalesId)
    {
        lineAmount = salesLine.SalesQty * (salesLine.SalesPrice / salesLine.PriceUnit);
    }

    if (custInvoiceTrans.RecId)
    {
        if (specialDiscSalesLine.SpecialDiscountId1 != '' && specialDiscSalesLine.SpecialDiscountPct1 != 0)
        {
            specialDiscInvoiceTrans.clear();
            specialDiscInvoiceTrans.initFromCustInvoiceTrans(custInvoiceTrans);
            specialDiscInvoiceTrans.initValue(specialDiscSalesLine.SpecialDiscountId1,
                                              specialDiscSalesLine.SpecialDiscountPct1,
                                              decRound(lineAmount*(specialDiscSalesLine.SpecialDiscountPct1/100),2),
                                              AVAPriceAdjustmentType::SpecialDiscount);
            specialDiscInvoiceTrans.insert();
            lineAmount -= specialDiscInvoiceTrans.SpecialDiscAmount;
        }
        if (specialDiscSalesLine.SpecialDiscountId2 != '' && specialDiscSalesLine.SpecialDiscountPct2 != 0)
        {
            specialDiscInvoiceTrans.clear();
            specialDiscInvoiceTrans.initFromCustInvoiceTrans(custInvoiceTrans);
            specialDiscInvoiceTrans.initValue(specialDiscSalesLine.SpecialDiscountId2,
                                              specialDiscSalesLine.SpecialDiscountPct2,
                                              decRound(lineAmount*(specialDiscSalesLine.SpecialDiscountPct2/100),2),
                                              AVAPriceAdjustmentType::SpecialDiscount);
            specialDiscInvoiceTrans.insert();
            lineAmount -= specialDiscInvoiceTrans.SpecialDiscAmount;
        }
        if (specialDiscSalesLine.SpecialDiscountId3 != '' && specialDiscSalesLine.SpecialDiscountPct3 != 0)
        {
            specialDiscInvoiceTrans.clear();
            specialDiscInvoiceTrans.initFromCustInvoiceTrans(custInvoiceTrans);
            specialDiscInvoiceTrans.initValue(specialDiscSalesLine.SpecialDiscountId3,
                                              specialDiscSalesLine.SpecialDiscountPct3,
                                              decRound(lineAmount*(specialDiscSalesLine.SpecialDiscountPct3/100),2),
                                              AVAPriceAdjustmentType::SpecialDiscount);
            specialDiscInvoiceTrans.insert();
            lineAmount -= specialDiscInvoiceTrans.SpecialDiscAmount;
        }
        if (specialDiscSalesLine.SpecialDiscountId4 != '' && specialDiscSalesLine.SpecialDiscountPct4 != 0)
        {
            specialDiscInvoiceTrans.clear();
            specialDiscInvoiceTrans.initFromCustInvoiceTrans(custInvoiceTrans);
            specialDiscInvoiceTrans.initValue(specialDiscSalesLine.SpecialDiscountId4,
                                              specialDiscSalesLine.SpecialDiscountPct4,
                                              decRound(lineAmount*(specialDiscSalesLine.SpecialDiscountPct4/100),2),
                                              AVAPriceAdjustmentType::SpecialDiscount);
            specialDiscInvoiceTrans.insert();
            lineAmount -= specialDiscInvoiceTrans.SpecialDiscAmount;
        }
        if (specialDiscSalesLine.SpecialDiscountId5 != '' && specialDiscSalesLine.SpecialDiscountPct5 != 0)
        {
            specialDiscInvoiceTrans.clear();
            specialDiscInvoiceTrans.initFromCustInvoiceTrans(custInvoiceTrans);
            specialDiscInvoiceTrans.initValue(specialDiscSalesLine.SpecialDiscountId5,
                                              specialDiscSalesLine.SpecialDiscountPct5,
                                              decRound(lineAmount*(specialDiscSalesLine.SpecialDiscountPct5/100),2),
                                              AVAPriceAdjustmentType::SpecialDiscount);
            specialDiscInvoiceTrans.insert();
            lineAmount -= specialDiscInvoiceTrans.SpecialDiscAmount;
        }
        if (specialDiscSalesLine.SpecialDiscountId6 != '' && specialDiscSalesLine.SpecialDiscountPct6 != 0)
        {
            specialDiscInvoiceTrans.clear();
            specialDiscInvoiceTrans.initFromCustInvoiceTrans(custInvoiceTrans);
            specialDiscInvoiceTrans.initValue(specialDiscSalesLine.SpecialDiscountId6,
                                              specialDiscSalesLine.SpecialDiscountPct6,
                                              decRound(lineAmount*(specialDiscSalesLine.SpecialDiscountPct6/100),2),
                                              AVAPriceAdjustmentType::SpecialDiscount);
            specialDiscInvoiceTrans.insert();
            lineAmount -= specialDiscInvoiceTrans.SpecialDiscAmount;
        }
        if (specialDiscSalesLine.SpecialDiscountId7 != '' && specialDiscSalesLine.SpecialDiscountPct7 != 0)
        {
            specialDiscInvoiceTrans.clear();
            specialDiscInvoiceTrans.initFromCustInvoiceTrans(custInvoiceTrans);
            specialDiscInvoiceTrans.initValue(specialDiscSalesLine.SpecialDiscountId7,
                                              specialDiscSalesLine.SpecialDiscountPct7,
                                              decRound(lineAmount*(specialDiscSalesLine.SpecialDiscountPct7/100),2),
                                              AVAPriceAdjustmentType::SpecialDiscount);
            specialDiscInvoiceTrans.insert();
            lineAmount -= specialDiscInvoiceTrans.SpecialDiscAmount;
        }

        if(salesLine.AVAPriceSurchargeCode)
        {
            specialDiscInvoiceTrans.clear();
            specialDiscInvoiceTrans.initFromCustInvoiceTrans(custInvoiceTrans);
            specialDiscInvoiceTrans.initValue(salesLine.AVAPriceSurchargeCode,
                                              salesLine.AVAPriceSurchargePercentage,
                                              decRound(lineAmount*(salesLine.AVAPriceSurchargePercentage/100), 2),
                                              AVAPriceAdjustmentType::PriceSurcharge);
            specialDiscInvoiceTrans.insert();
            lineAmount += specialDiscInvoiceTrans.SpecialDiscAmount;
        }
    }
}
